function parseRateForSorting(rateStr) {
  const matches = rateStr.match(/\d+/g);
  if (!matches || matches.length === 0) return 0;
  if (matches.length >= 2) {
    return (parseFloat(matches[0]) + parseFloat(matches[1])) / 2;
  }
  return parseFloat(matches[0]);
}
