class ReceiptByteBuilder {
  constructor() {
    this.buffer = [];
    this.encoder = new TextEncoder();
    this.init();
  }
  // ESC @ - Initialize printer
  init() {
    this.buffer.push(27, 64);
    return this;
  }
  // ESC a n - Set alignment
  // 0 or 0x00: Left
  // 1 or 0x01: Center
  // 2 or 0x02: Right
  alignLeft() {
    this.buffer.push(27, 97, 0);
    return this;
  }
  alignCenter() {
    this.buffer.push(27, 97, 1);
    return this;
  }
  alignRight() {
    this.buffer.push(27, 97, 2);
    return this;
  }
  // GS ! n - Set character size
  // doubleHeight: 0x1D, 0x21, 0x10
  textDoubleHeight() {
    this.buffer.push(29, 33, 16);
    return this;
  }
  // doubleWidth: 0x1D, 0x21, 0x01
  textDoubleWidth() {
    this.buffer.push(29, 33, 1);
    return this;
  }
  // doubleHeight and doubleWidth: 0x1D, 0x21, 0x11
  textDoubleBoth() {
    this.buffer.push(29, 33, 17);
    return this;
  }
  // Reset text size to normal: GS ! 00 -> 1D 21 00
  textNormalSize() {
    this.buffer.push(29, 33, 0);
    return this;
  }
  // Raw text feed
  text(str) {
    const bytes = this.encoder.encode(str);
    for (let i = 0; i < bytes.length; i++) {
      this.buffer.push(bytes[i]);
    }
    return this;
  }
  line(str = "") {
    this.text(str + "\n");
    return this;
  }
  // Feed n line breaks
  feed(n = 1) {
    for (let i = 0; i < n; i++) {
      this.buffer.push(10);
    }
    return this;
  }
  // GS V 66 00 -> 1D 56 42 00 paper cut command
  cutPaper() {
    this.buffer.push(29, 86, 66, 0);
    return this;
  }
  // Get raw bytes
  getBytes() {
    return new Uint8Array(this.buffer);
  }
}
function serializeSaleToReceiptBytes(sale, bandName, items) {
  const builder = new ReceiptByteBuilder();
  builder.alignCenter().textDoubleBoth().line(bandName.toUpperCase()).textNormalSize().line("================================").alignCenter().line("** OFFICIAL MERCHANDISE SLIP **").alignLeft().feed(1).line(`TRANSACTION ID: ${sale.id.toUpperCase()}`).line(`DATE: ${new Date(sale.created_at).toLocaleString()}`).line(`PAYMENT METHOD: ${sale.payment_method.toUpperCase()}`).line("--------------------------------").feed(1);
  let totalQty = 0;
  if (sale.cart_items && sale.cart_items.length > 0) {
    sale.cart_items.forEach((item) => {
      const name = item?.name + (item.variantName ? ` [${item.variantName.toUpperCase()}]` : "");
      const lineStr = `${item.quantity}x ${name}`;
      const priceStr = `$${(item.price * item.quantity).toFixed(2)}`;
      const spaceNeeded = 32 - lineStr.length - priceStr.length;
      const spaces = spaceNeeded > 0 ? " ".repeat(spaceNeeded) : " ";
      builder.line(`${lineStr}${spaces}${priceStr}`);
      totalQty += item.quantity;
    });
  } else {
    const mockItemStr = `${sale.quantity || 1}x ${sale.item_name || "Custom Sale"}`;
    const priceStr = `$${(sale.amount || 0).toFixed(2)}`;
    const spaceNeeded = 32 - mockItemStr.length - priceStr.length;
    const spaces = spaceNeeded > 0 ? " ".repeat(spaceNeeded) : " ";
    builder.line(`${mockItemStr}${spaces}${priceStr}`);
    totalQty = sale.quantity || 1;
  }
  builder.feed(1).line("--------------------------------").alignRight().textDoubleHeight().line(`TOTAL ITEMS: ${totalQty}`).line(`TOTAL PAID: $${(sale.amount || 0).toFixed(2)}`).textNormalSize().feed(2).alignCenter().line("THANK YOU FOR SUPPORTING LIVE MUSIC!").line("Powered by NEXUS CORE").feed(3).cutPaper();
  return builder.getBytes();
}

