      const updatedList = bList.map((r) => {
        if (r.title === title) {
          const sFormats = r.formats || { vinyl: { warehouse_qty: 0 }, cd: { warehouse_qty: 0 }, cassette: { warehouse_qty: 0 } };
          return {
            ...r,
            formats: {
              ...sFormats,
              [format]: { warehouse_qty: Math.max(0, currentQty - qty) }
            }
          };
        }
        return r;
      });
      return { ...prev, [bandId]: updatedList };
